  const isDeprecating = new DeprecatedFeatureRegistry().isDeprecated(name);

  feature = getSafeObject(feature)
  if (isDeprecating) {
    // Deprecate the feature by making the opt-out functionality enabled.
    feature.opts = new DeprecatedFeatureOptions(name, true);
    await this.storeFeature(feature);
  }

  // Return whether it is deprecated.
  return isDeprecating;
}
```

